mapper.update:
UPDATE T_JOB_RUN
   SET STATUS      = #{status}
      ,TOTAL_COUNT = #{totalCount}
      ,FAIL_COUNT  = #{failCount}
      ,MESSAGE     = #{message}
      ,ENDED_AT    = NOW()
 WHERE 1=1
   AND ID = #{runId}

mapper.select:
SELECT  COUNT(*)
  FROM T_JOB_RUN
 WHERE 1=1
   AND JOB_NAME   = #{jobName}
   AND STATUS     IN ('SUCCESS', 'PARTIAL')
   AND STARTED_AT >= #{since}

SELECT  COUNT(*)
  FROM T_JOB_RUN
 WHERE 1=1
   AND JOB_NAME   = #{jobName}
   AND STATUS     IN ('FAIL', 'PARTIAL')
   AND STARTED_AT >= #{since}

   AND ID         <> #{runId}
